// Parse and validate the LLM classification output with deterministic fallbacks.
const envelope = $('When Called by Another Workflow').first().json;
const raw = ($input.first().json.output || '').trim();

const ALLOWED_INTENTS = [
  'greeting','faq','product_question','pricing','order_status','order_issue',
  'payment_issue','refund_request','cancellation','technical_support','complaint',
  'account_issue','shipping','human_agent_request','unknown'
];

function extractJson(text) {
  if (!text) return null;
  const cleaned = text
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try {
    return JSON.parse(cleaned.slice(start, end + 1));
  } catch (e) {
    return null;
  }
}

const parsed = extractJson(raw);
const fallback = { intent: 'unknown', category: 'unknown', confidence: 0.3, requires_human: false };

let intent = parsed && typeof parsed.intent === 'string' ? parsed.intent.trim().toLowerCase() : fallback.intent;
if (!ALLOWED_INTENTS.includes(intent)) intent = fallback.intent;

let confidence = parsed && Number(parsed.confidence);
if (!Number.isFinite(confidence)) confidence = fallback.confidence;
confidence = Math.max(0, Math.min(1, confidence));

let requires_human = parsed ? Boolean(parsed.requires_human) : fallback.requires_human;
const category = parsed && typeof parsed.category === 'string' && parsed.category.trim()
  ? parsed.category.trim().slice(0, 100)
  : intent;

const classification = { intent, category, confidence, requires_human, raw };
return [{ json: { ...envelope, classification } }];
